<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/bootstrap.php';

/**
 * Staff download CMS API.
 *
 * GET lists downloads. POST accepts JSON for toggle/delete and multipart form
 * data for create (title plus an uploaded file). Upload types and signatures use
 * the repository upload helper; paths are always generated by that helper.
 */
function mobileAdminDownloadsPayload(): array
{
    $contentType = strtolower(trim(explode(';', (string) ($_SERVER['CONTENT_TYPE'] ?? ''))[0]));
    if ($contentType === 'application/json') {
        return mobileApiReadJson(16384);
    }
    if ($contentType === 'multipart/form-data' || $contentType === 'application/x-www-form-urlencoded') {
        return $_POST;
    }

    mobileApiJson(['error' => ['code' => 'unsupported_media_type', 'message' => 'Send JSON or multipart form data.']], 415);
}

$method = strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET'));
if (!in_array($method, ['GET', 'POST'], true)) {
    header('Allow: GET, POST');
    mobileApiJson(['error' => ['code' => 'method_not_allowed', 'message' => 'Use GET or POST.']], 405);
}

$newFile = '';
try {
    $db = getDatabaseConnection();
    $identity = mobileApiRequireIdentity($db);
    if ($identity['account_type'] !== 'staff' || !canAccessModule('downloads', $identity['account'])) {
        mobileApiJson(['error' => ['code' => 'forbidden', 'message' => 'You do not have permission to manage downloads.']], 403);
    }
    if ($method === 'POST') {
        mobileApiBeginIdempotentWrite($db, $identity);
    }

    if ($method === 'GET') {
        $rows = fetchRows(
            $db,
            'SELECT id, files_text AS title, files_file AS file, files_status AS status,
                    files_creation_time AS created_at
             FROM files ORDER BY ' . downloadListOrderSql($db) . ' LIMIT 200'
        );
        foreach ($rows as &$row) {
            $file = publicMediaBasename((string) ($row['file'] ?? ''));
            $row['file_url'] = $file === '' ? null : publicSiteUrl('files_file/' . $file);
            $row['status'] = (int) ($row['status'] ?? 0) === 1;
        }
        unset($row);
        mobileApiJson(['data' => ['downloads' => $rows]]);
    }

    $payload = mobileAdminDownloadsPayload();
    $action = $payload['action'] ?? null;
    if (!is_string($action) || !in_array($action, ['create', 'toggle', 'delete'], true)) {
        mobileApiJson(['error' => ['code' => 'invalid_action', 'message' => 'Choose create, toggle or delete.']], 422);
    }

    if ($action === 'create') {
        $title = $payload['title'] ?? null;
        if (!is_string($title) || trim($title) === '' || mb_strlen(trim($title), 'UTF-8') > 255) {
            mobileApiJson(['error' => ['code' => 'invalid_download', 'message' => 'Title is required and must be at most 255 characters.']], 422);
        }
        $newFile = storeUploadedFile(
            'files_file',
            'files_file',
            ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'jpg', 'jpeg', 'png'],
            30 * 1024 * 1024,
            true
        ) ?? '';
        if ($newFile === '') {
            mobileApiJson(['error' => ['code' => 'invalid_download', 'message' => 'Attach a file to create a download.']], 422);
        }
        if (columnExists($db, 'files', 'sort_order')) {
            $db->prepare('INSERT INTO files (files_text, files_file, files_status, sort_order) VALUES (:title, :file, 1, :sort)')
                ->execute(['title' => trim($title), 'file' => $newFile, 'sort' => nextDownloadSortOrder($db)]);
        } else {
            $db->prepare('INSERT INTO files (files_text, files_file, files_status) VALUES (:title, :file, 1)')
                ->execute(['title' => trim($title), 'file' => $newFile]);
        }
        mobileApiJson(['data' => ['id' => (int) $db->lastInsertId(), 'status' => 'created']], 201);
    }

    $downloadId = filter_var($payload['id'] ?? null, FILTER_VALIDATE_INT);
    if (!is_int($downloadId) || $downloadId < 1) {
        mobileApiJson(['error' => ['code' => 'invalid_download', 'message' => 'A valid download ID is required.']], 422);
    }
    if ($action === 'toggle') {
        $statement = $db->prepare('UPDATE files SET files_status = IF(files_status = 1, 0, 1) WHERE id = :id');
        $statement->execute(['id' => $downloadId]);
        if ($statement->rowCount() !== 1) {
            mobileApiJson(['error' => ['code' => 'not_found', 'message' => 'Download not found.']], 404);
        }
        mobileApiJson(['data' => ['id' => $downloadId, 'status' => 'toggled']]);
    }

    if (!deleteDatabaseRowWithMedia($db, 'files', $downloadId, ['files_file' => 'files_file'])) {
        mobileApiJson(['error' => ['code' => 'not_found', 'message' => 'Download not found.']], 404);
    }
    mobileApiJson(['data' => ['id' => $downloadId, 'status' => 'deleted']]);
} catch (PDOException $exception) {
    if ($newFile !== '') {
        deletePublicMediaFile('files_file', $newFile);
    }
    mobileApiDatabaseFailure($exception, 'admin downloads');
} catch (RuntimeException $exception) {
    if ($newFile !== '') {
        deletePublicMediaFile('files_file', $newFile);
    }
    mobileApiJson(['error' => ['code' => 'invalid_download', 'message' => $exception->getMessage()]], 422);
} catch (Throwable $exception) {
    if ($newFile !== '') {
        deletePublicMediaFile('files_file', $newFile);
    }
    error_log('Mobile API admin downloads failed: ' . $exception->getMessage());
    mobileApiJson(['error' => ['code' => 'service_unavailable', 'message' => 'The download request could not be completed.']], 500);
}
